package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheet;

/**
 * A claim's audit record: its person, its amount as the screen shows it, its date, and its number
 * when it has one (a voided claim keeps the number it had).
 */
final class ClaimAudit {
    private ClaimAudit() {}

    static String line(String event, Sheet sheet, String user, Person person, Claim claim) {
        ClaimResponse shown = ClaimResponse.from(claim);
        return event + " sheet=" + sheet.id() + " by=" + user + " person=" + person.getName()
                + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.getNumber() == null ? "" : " number=" + claim.getNumber());
    }
}
package net.officefloor.hq.app.claim;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;

/** Records the approval; the line ends with the due it was settled at (n/a when its grade had no rate). */
public class AuditClaimApproved {
    public void audit(@Val Sheet sheet, @Val Claim claim, PersonRepository people,
            HttpServletRequest request, Audit audit) {
        audit.record(ClaimAudit.line("CLAIM_APPROVED", sheet, Audit.user(request),
                people.find(sheet.id(), claim.getPersonId()), claim)
                + " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString()));
    }
}
package net.officefloor.hq.app.claim;

/** A status change, or an edit, the claim's current status does not allow. */
public class InvalidClaimStatusException extends Exception {
    public InvalidClaimStatusException(ClaimStatus from, ClaimStatus to) {
        super("A " + from + " claim cannot become " + to);
    }

    /** An edit of a claim that is no longer a draft. */
    public InvalidClaimStatusException(ClaimStatus status) {
        super("A " + status + " claim cannot be edited");
    }

    /** Any other change its status does not allow. */
    public InvalidClaimStatusException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadClaim {
    public void load(@PathVariable("claimId") String claimId, @Val Sheet sheet,
            ClaimRepository repository, Out<Claim> claimOut) throws ClaimNotFoundException {
        Claim claim = null;
        try {
            claim = repository.find(sheet.id(), Long.parseLong(claimId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (claim == null) throw new ClaimNotFoundException(claimId);
        claimOut.set(claim);
    }
}
